<?php require 'config.php';$title='خدمات التعديل';require 'header.php';$services=array_filter(read_json('services.json',[]),fn($s)=>!empty($s['active']));?><h1>🛠️ خدمات التعديل</h1><div class="grid"><?php foreach($services as $s):?><article class="card"><img class="product-img" src="<?=e($s['image']??'')?>" onerror="this.style.display='none'"><h2><?=e($s['name'])?></h2><p><?=nl2br(e($s['description']??''))?></p><div class="price"><?=money((float)($s['price']??0))?></div></article><?php endforeach;if(!$services):?><div class="notice">لا توجد خدمات مضافة حالياً.</div><?php endif;?></div><?php require 'footer.php';?>